import { useMemo, useState } from "react";
import Calendar from "@/core/components/primitives/calendar/calendar";
import { DateHelper, TodayHelper, createDate } from "@/core/helpers";
import { CalendarDateFieldDataProps } from "@/core/components/primitives/calendar/types/calendar-types";
import structure from "@/core/styling/structure.module.less";
import { DateMap, DateSet } from "@/core/helpers/date-helper";
import { sortBy } from "lodash-es";
import { withIsFullyBooked } from "@/core/components/primitives/calendar/modifiers/withIsFullyBooked";

type SelectedDates = {
  date: string;
  fullDate: string;
};

export type CalendarDatesProps = {
  startDate: string;
  endDate: string;
  selectedDates: Array<SelectedDates>;
};

const getSortedCalendarData = (calendarDates: CalendarDatesProps, removeDaysInThePast = true) => {
  const intervalData = getCalendarDataFromDateInterval(calendarDates);
  const allData = addSelectedDatesToCalendarData(intervalData, calendarDates);

  const filteredDataByDate = filterUniqueOnProp(allData, "date");
  const filteredDataByPassedDate = !removeDaysInThePast
    ? filteredDataByDate
    : filteredDataByDate.filter((data) => !DateHelper.hasDatePassed(data.date) || DateHelper.isToday(data.date));
  return sortBy(filteredDataByPassedDate, "date");
};

const getCalendarDataFromDateInterval = (calendarDates: CalendarDatesProps) => {
  const calendarData: Array<CalendarDateFieldDataProps> = [];

  if (calendarDates?.startDate < calendarDates?.endDate) {
    const endDate = createDate(calendarDates.endDate);
    let currentDate = createDate(calendarDates.startDate);

    while (currentDate <= endDate) {
      calendarData.push({
        date: createDate(currentDate),
        open: true,
      });
      currentDate = DateHelper.addDays(currentDate, 1);
    }
  }

  return calendarData;
};

const addSelectedDatesToCalendarData = (
  calendarData: Array<CalendarDateFieldDataProps>,
  calendarDates: CalendarDatesProps,
) => {
  const selectedDatesData: Array<CalendarDateFieldDataProps> = [];

  calendarDates?.selectedDates?.forEach((selectedDate) => {
    selectedDatesData.push({
      date: createDate(selectedDate.fullDate),
      open: true,
    });
  });

  return [...calendarData, ...selectedDatesData];
};

const filterUniqueOnProp = (filterArray: Array<CalendarDateFieldDataProps>, prop: "date") => {
  const uniqueDates = new Set<string>();

  return filterArray.filter((item) => {
    const dateAsString = DateHelper.toStringYYYYMMDD(item[prop]);
    if (!uniqueDates.has(dateAsString)) {
      uniqueDates.add(dateAsString);
      return true;
    }
    return false;
  });
};

type CalendarDateFieldProps = {
  /**
   * The selectable days. `startDate` and `endDate` are YYYY-MM-DD strings and every day in between is
   * selectable; `selectedDates` adds extra selectable days by their `fullDate` (YYYY-MM-DD).
   */
  calendarDates: CalendarDatesProps;
  /**
   * Same shape as `calendarDates`. These days are disabled and rendered with the fully-booked marker
   * ("Fullbokat" is added to the day's accessible name).
   */
  fullyBookedDates?: CalendarDatesProps;
  /** Fires with the clicked day (local midnight) - only for selectable days, never for disabled ones. */
  onChangeDate: (date: Date) => void;
  /** Hides days before today (read from `TodayHelper.getNow()`). Defaults to true. */
  removeDaysInThePast?: boolean;
};

export const CalendarDateField = ({
  calendarDates,
  fullyBookedDates,
  onChangeDate,
  removeDaysInThePast = true,
}: CalendarDateFieldProps) => {
  const [selectedDate, setSelectedDate] = useState<Date>();
  const calendarData = useMemo(
    () => getSortedCalendarData(calendarDates, removeDaysInThePast),
    [calendarDates, removeDaysInThePast],
  );

  const fullyBookedDays = useMemo(() => {
    if (!fullyBookedDates) return new DateMap<{ isFullyBooked?: boolean }>([]);
    const sortedDates = getSortedCalendarData(fullyBookedDates, removeDaysInThePast);
    return new DateMap<{ isFullyBooked?: boolean }>(
      sortedDates.map((d) => [DateHelper.toStringYYYYMMDD(d.date), { isFullyBooked: true }]),
    );
  }, [fullyBookedDates, removeDaysInThePast]);

  const fullyBooked = withIsFullyBooked(fullyBookedDays);
  const startDate = calendarData?.[0]?.date ?? TodayHelper.getNow();
  const endDate = calendarData?.at(-1)?.date ?? TodayHelper.getNow();
  const [currentDisplayedMonth, setCurrentDisplayedMonth] = useState(startDate);

  const handleDateChange = (changedDate: Date) => {
    const data = calendarData?.find((d) => DateHelper.isEqualYYYYMMDD(d.date, changedDate));
    if (data?.open) {
      setSelectedDate(data.date);
      onChangeDate(data.date);
    }
  };

  const days = new DateSet(calendarData?.map((d) => d.date));

  return (
    <section>
      <div>
        <div className={`${structure.blockMaxWidthS}`}>
          <Calendar
            currentDisplayedMonth={currentDisplayedMonth}
            startDate={startDate}
            endDate={endDate}
            changedMonth={(newMonth: Date) => setCurrentDisplayedMonth(newMonth)}
            changeDate={(newDate) => handleDateChange(newDate)}
            selectedDate={selectedDate}
            disabledDates={(d) => !days.has(d) || fullyBookedDays.has(d)}
            modifiers={fullyBooked}
          />
        </div>
      </div>
    </section>
  );
};
